mapper.insert:
INSERT INTO resource_link_preview_retirement_manifest (
    stored_file_id, storage_scope_code, storage_key, retirement_status_code
) VALUES (
    #{storedFileId}, #{storageScope}, #{storageKey}, #{status}
)

mapper.update:
UPDATE resource_link_preview_retirement_manifest
SET retirement_status_code = 'DELETED', attempt_count = attempt_count + 1,
    failure_reason = NULL, completed_dttm = #{completedDttm}
WHERE resource_link_preview_retirement_manifest_id = #{manifestId}

UPDATE resource_link_preview_retirement_manifest
SET retirement_status_code = 'FAILED', attempt_count = attempt_count + 1,
    failure_reason = #{failureReason}
WHERE resource_link_preview_retirement_manifest_id = #{manifestId}
